from pathlib import Path
import json,html,hashlib
root=Path.cwd();out=root/'output/direct-sdk-verification';read=lambda f:json.loads((out/f).read_text(encoding='utf-8-sig'));esc=lambda s:html.escape(str(s))
files=['auth-smoke-results.json','auth-callback-results.json','bootstrap-rules-results.json','empty-meta-results.json','integration-results.json','permissions-results.json','snapshot-results.json','stock-results.json','spec-results.json','source-results.json','member-batch-results.json','restore-results.json','restore-cancel-results.json','adoption-results.json','submission-results.json','ui-results.json','built-results.json']
groups={f:read(f) for f in files};assert all(r['status']=='PASS' for d in groups.values() for r in d['results']);unit=read('unit-results.json');assert unit['numPassedTests']==299 and unit['numFailedTests']==0;checkpoint=read('checkpoint-verification.json');copy=read('default-copy-verification.json');reimport=read('reimport-results.json');assert all(r['status']=='PASS' for r in reimport['results']);assert checkpoint['previousV24BlobBytesPreserved']==3442 and copy['filesCompared']==7113
count=299+sum(len(d['results']) for d in groups.values());assert count==376
summary={'status':'PASS','softwareScenarios':count,'unitTests':299,'directSdkScenarios':count-299,'groups':{f:len(d['results']) for f,d in groups.items()},'representativeReimportChecks':5,'pdfFiles':5,'pdfPagesVisuallyReviewed':12,'firestoreRulesSha256':hashlib.sha256((root/'firestore.rules').read_bytes()).hexdigest(),'storageRulesSha256':hashlib.sha256((root/'storage.rules').read_bytes()).hexdigest(),'scope':'Local direct-SDK software checks; full engineering/owner/cloud acceptance remains pending'}
(out/'verification-summary.json').write_text(json.dumps(summary,indent=2),encoding='utf-8')
labels=['การสมัคร/เข้าสู่ระบบจริง','รีเฟรชหลังเข้าสู่ระบบ','การสมัครพร้อมกัน/ป้องกันยกระดับสิทธิ์','เริ่มจาก metadata เดิมที่ยังว่าง','หลายโครงการ/ข้อมูล BBS','สิทธิ์ผู้ดูแลโครงการ','Snapshot/ส่งออกจริง','สต็อก/เศษเหล็ก','เปลี่ยนสเป็ค/คืนข้อมูล','รับแบบ/Mark/Revision','รับแบบสมาชิกเป็นชุด','ZIP Restore จริง','ยกเลิก Restore บางส่วน','นำไฟล์เดิมเข้าทะเบียน','ชุดส่งตรวจจริง','หน้าจอ/ข้อมูลยังไม่บันทึก','แอปที่ build แล้ว']
rows=''.join(f'<tr><td>{esc(label)}</td><td>{len(groups[f]["results"])} PASS</td><td><a href="{f}">ผลทดสอบ</a></td></tr>' for label,f in zip(labels,files))
checks=''.join('<details><summary>'+esc(label)+'</summary><ul>'+''.join('<li>'+esc(r['name'])+'</li>' for r in groups[f]['results'])+'</ul></details>' for label,f in zip(labels,files))
shots=[('admin-users-desktop.png','MasterAdmin อนุมัติและมอบหมายโครงการ'),('profile-stale-preserved.png','รักษาข้อความในโปรไฟล์เมื่อข้อมูลเปลี่ยน'),('member-draft-role-reduced.png','ลดสิทธิ์แล้วเก็บข้อความที่ยังไม่บันทึก'),('assigned-project-mobile.png','โครงการที่ได้รับสิทธิ์บนจอมือถือ'),('built-project-team.png','ทีมในแอปที่ build แล้ว'),('built-3D.png','ข้อมูลจริงในมุมมอง 3D')]
gallery=''.join(f'<figure><a href="{name}"><img src="{name}" loading="lazy" alt="{esc(title)}"></a><figcaption>{esc(title)}</figcaption></figure>' for name,title in shots)
artifacts=[('direct-bbs-A3.pdf','BBS A3 — 2 หน้า'),('direct-bbs-A1.pdf','BBS A1 — 1 หน้า'),('direct-cutting-A4.pdf','ตารางตัด/ดัด A4 — 7 หน้า'),('direct-boq-A3.pdf','BOQ A3 — 1 หน้า'),('direct-transmittal.pdf','ใบส่งเอกสาร A4 — 1 หน้า'),('direct-boq-bbs.xlsx','Excel BOQ/BBS'),('direct-submission.zip','ชุดส่งตรวจ ZIP'),('direct-restored-backup.zip','Backup ของโครงการที่กู้คืน')]
